using static StrataLint.Scribe.DefinitionDsl;
namespace StrataLint.Scribe.Blueprint.D5.S3.Combinatorics.Circle.FourNegative.SecondPeakEqualTailCones;
internal sealed class ScheduleDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Upper-union schedules in the actual source", H("From seam gates to every natural prefix"),
        Blocks(
            Paragraph(Text("The twelve chart gates bound the cumulative old and new postterminal seams. The fourth seam is exactly zero. The packet Checks predicate combines these interfaces with nonnegative positive-bank entries and nonpositive actual terminals. The existing checks_strip theorem then controls every take-prefix within each bank as well as the terminal boundaries.")),
            Paragraph(Text("The old packets are the four physical banks with terminals W,U,X,V. The enlarged packets use the same inherited labels, and place the true fresh label k at the start of bank 3. Its doubled mass 2A is included in the third-bank calculation. Both strips are therefore proved for one literal physical word, rather than separately selected orders in the two rows.")),
            Paragraph(Text("The inventory bounds j=pre.length by k=a+b+2s and permits mapping inherited labels into Fin k. The marked-word identity identifies the enlarged word with earWord(k,sigma,j), preserving Fin.castSucc on every inherited occurrence. Finally the exact old zero total and enlarged zero total give both actual OriginalOrder conclusions, with all natural prefix lengths, including zero and lengths beyond the complete word. The premises remain the two upper clauses and s>=2."))), []));
}
